package com.cdac.cssip.user.controller; import com.cdac.cssip.common.security.AuthenticatedUser; import com.cdac.cssip.user.dto.UserDtos.*; import com.cdac.cssip.user.service.UserFacade; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.*;
public final class ProfileControllers{private ProfileControllers(){} @RestController @RequestMapping("/student") @RequiredArgsConstructor @PreAuthorize("hasRole('STUDENT')") public static class StudentController{private final UserFacade f;@GetMapping("/dashboard")public String d(){return "Welcome Student";}@GetMapping("/profile")public UserView p(@AuthenticationPrincipal AuthenticatedUser u){return f.byId(u.userId());}@PutMapping("/profile")public UserView p(@AuthenticationPrincipal AuthenticatedUser u,@RequestBody StudentUpdate r){return f.studentUpdate(u.userId(),r);}}
 @RestController @RequestMapping("/staff") @RequiredArgsConstructor @PreAuthorize("hasRole('STAFF')") public static class StaffController{private final UserFacade f;@GetMapping("/dashboard")public String d(){return "Welcome Staff";}@GetMapping("/profile")public UserView p(@AuthenticationPrincipal AuthenticatedUser u){return f.byId(u.userId());}@PutMapping("/profile")public UserView p(@AuthenticationPrincipal AuthenticatedUser u,@RequestBody StaffUpdate r){return f.staffUpdate(u.userId(),r);}@GetMapping("/students")public List<UserView>s(){return f.students();}@GetMapping("/students/{id}")public UserView s(@PathVariable Long id){return f.byId(id);}@GetMapping("/students/search")public List<UserView>s(@RequestParam String keyword){return f.searchStudents(keyword);}}}
